async (page) => {
  await page.reload();
  await page.waitForTimeout(600);

  const readState = () => page.evaluate(() => {
    const c = document.querySelector('canvas');
    const g = c.getContext('2d');
    const { width: w, height: h } = c;
    const d = g.getImageData(0, 0, w, h).data;
    const scale = w / window.innerWidth;
    const step = 3;
    let px = 0, py = 0, pn = 0;
    const raw = [];
    for (let y = 0; y < h; y += step) {
      for (let x = 0; x < w; x += step) {
        const i = (y * w + x) * 4;
        const r = d[i], gg = d[i + 1], b = d[i + 2];
        if (r > 235 && gg > 235 && b > 235) { px += x; py += y; pn++; }
        else if (r > 200 && gg > 135 && gg < 230 && b < 160) raw.push([x / scale, y / scale]);
      }
    }
    const clusters = [];
    for (const [x, y] of raw) {
      const c0 = clusters.find(q => Math.abs(q.x - x) < 24 && Math.abs(q.y - y) < 24);
      if (c0) { c0.x = (c0.x * c0.n + x) / (c0.n + 1); c0.y = (c0.y * c0.n + y) / (c0.n + 1); c0.n++; }
      else clusters.push({ x, y, n: 1 });
    }
    return {
      player: pn ? { x: px / pn / scale, y: py / pn / scale } : null,
      orbs: clusters.filter(o => o.n > 3).map(o => ({ x: o.x, y: o.y })),
      score: document.getElementById('score').textContent,
      time: document.getElementById('time').textContent,
      won: document.getElementById('overlay').classList.contains('show'),
      final: document.getElementById('finalTime').textContent
    };
  });

  const hold = async (key, ms) => {
    await page.keyboard.down(key);
    await page.waitForTimeout(ms);
    await page.keyboard.up(key);
  };

  let state = await readState();
  const initial = { player: state.player, orbs: state.orbs.length, score: state.score };

  const deadline = Date.now() + 70000;
  while (!state.won && Date.now() < deadline) {
    state = await readState();
    if (!state.player) break;
    const target = state.orbs
      .map(o => ({ ...o, d: Math.hypot(o.x - state.player.x, o.y - state.player.y) }))
      .sort((a, b) => a.d - b.d)[0];
    if (!target) break;
    for (let i = 0; i < 6; i++) {
      state = await readState();
      const dx = target.x - state.player.x;
      if (Math.abs(dx) < 5) break;
      await hold(dx > 0 ? 'ArrowRight' : 'ArrowLeft', Math.min(500, Math.max(35, (Math.abs(dx) / 430) * 1000)));
    }
    for (let i = 0; i < 6; i++) {
      state = await readState();
      const dy = target.y - state.player.y;
      if (Math.abs(dy) < 5) break;
      await hold(dy > 0 ? 'ArrowDown' : 'ArrowUp', Math.min(500, Math.max(35, (Math.abs(dy) / 430) * 1000)));
    }
    state = await readState();
    if (state.won) break;
  }

  return {
    initial,
    score: state.score,
    time: state.time,
    won: state.won,
    final: state.final,
    best: await page.evaluate(() => localStorage.getItem('square.best.v1'))
  };
}

